import hashlib,json,platform,random

def resample_experiment(data,config):
    # OWN iid empirical resample demonstration,NOTa time-series confidence interval.
    if type(data) is not list or not 1<=len(data)<=32 or any(type(x) is not int or not -10000<=x<=10000 for x in data):
        raise ValueError("invalid integer bps data")
    if type(config) is not dict or set(config)!={"version","seed","resamples"}:
        raise ValueError("invalid experiment config keys")
    if type(config["version"]) is not int or config["version"]!=1:
        raise ValueError("unsupported experiment version")
    if type(config["seed"]) is not int or not 0<=config["seed"]<2**32:
        raise ValueError("invalid seed")
    if type(config["resamples"]) is not int or not 1<=config["resamples"]<=100:
        raise ValueError("invalid resample budget")
    manifest={"kernel":"iid-mean-bps-v1","python":platform.python_version(),"data_bps":data[:],"config":dict(config)}
    raw=json.dumps(manifest,sort_keys=True,separators=(",",":"),ensure_ascii=True,allow_nan=False).encode("utf-8")
    identity=hashlib.sha256(raw).hexdigest()
    rng=random.Random(config["seed"])
    sums=tuple(sum(data[rng.randrange(len(data))] for _ in range(len(data))) for _ in range(config["resamples"]))
    return identity,raw.decode("utf-8"),sums,len(data)

config={"version":1,"seed":7,"resamples":4}
a=resample_experiment([10,-5,20],config)
b=resample_experiment([10,-5,20],dict(reversed(list(config.items()))))
print(a[2],"denominator",a[3])
print("replay",a==b)
random.seed(999);random.random()
print("global RNGindependent",resample_experiment([10,-5,20],config)==a)
print("changed data identity",resample_experiment([10,-5,21],config)[0]!=a[0])
try:resample_experiment([10],{**config,"unknown":0})
except ValueError as error:print(error)
